}

export type StepId = "initial" | "more_flights" | "nonstop_filter";
/** Position of an itinerary inside one captured request: `order` is 0-based (best first, then others). */
export interface Appearance { group: "best" | "other"; order: number; price: number }

export interface FlightView {
  id: number;
  key: string;
  /** F3/F2/F4: where this itinerary appeared — initial 22, all 300, nonstop 18 */
  seen: Partial<Record<StepId, Appearance>>;
  group: "best" | "other";
  rankInGroup: number;
  displayOrder: number;
  price: number;
  origin: string;
  originName: string;
  destination: string;
  destinationName: string;
  departDate: string;
  departTime: string;
  arriveDate: string;
  arriveTime: string;
  dayOffset: number;
  durationMin: number;
  stops: number;
  airlines: { code: string; name: string; alliance: string | null }[];
  /** v4: airline text as the original shows it (co-marketing partners after " · ", real names for multi-airline trips) */
  airlineLabel?: string;
  layovers: LayoverView[];
  legs: LegView[];
  co2: { g: number; typical: number; pct: number; level: number; label: string };
  assistance: { code: string; name: string; url: string }[];
  baggage: { code: string; name: string; url: string }[];
}

export interface SnapshotInfo {
  id: number;
  route: string;
  travelDate: string;
  capturedAt: string;
  moreNotEmbedded: number | null;
  priceMax: number;
  layoverMin: number;
  layoverMax: number;
  durationMin: number;
  durationMax: number;
}

export interface StepInsights {
  step: StepId;
  stopsFilter: number;
  bestCount: number;
  otherCount: number;
  notLoaded: number | null;
  lowestNow: number;
  typicalLow: number;
  typicalHigh: number;
  reference: number | null;
}

export interface BookingOption {
  sellerCode: string;
  sellerName: string;
  isAirline: boolean;
  price: number;
  extraFee: number | null;
  domain: string | null;
}

export interface BookingInsights { typicalLow: number; typicalHigh: number; reference: number | null; lowestNow: number | null }

export interface Insights {
  steps: StepInsights[];
  lowestNow: number;
  typicalLow: number;
  typicalHigh: number;
  history: { date: string; price: number }[];
  cheaper: { date: string; price: number }[];
}

export interface AirlineOpt { code: string; name: string; alliance: string | null }
export interface AirportOpt { code: string; city: string | null; name: string | null }
export function baht(n: number): string {
  return "฿" + Math.round(n).toLocaleString("en-US");
}

/** C7: calendar/estimate prices are rounded to the nearest 10. */
export function bahtApprox(n: number): string {
  return baht(Math.round(n / 10) * 10);
}

export function kg(grams: number): string {
  return `${Math.round(grams / 1000).toLocaleString("en-US")} กก.`;
}
