  for (const r of roles) { mn += Math.min(ro[r] || 0, rc[r] || 0); mx += Math.max(ro[r] || 0, rc[r] || 0); }
  const keyCov = (KEY.length - missing.length) / KEY.length;
  out.versions[v] = {
