test('F01','โหลดครบ 300 เที่ยวบินจริง',async p=>{await more(p);assert.equal(await rows(p).count(),300);});
test('F02','โหลดทั้งหมดครั้งเดียวไม่มีหน้าถัดไป',async p=>{await more(p);assert.equal(await rows(p).count(),300);await absent(button(p,/^ดูเที่ยวบินเพิ่มเติม/));await absent(button(p,/หน้าถัดไป/));});
test('F03','ผลแรก 22 รายการคงเดิมหลังโหลด',async p=>{await count(p,22);const before=await rows(p).allTextContents();await p.reload();await rows(p).first().waitFor();assert.deepEqual(await rows(p).allTextContents(),before);});
test('F04','บินตรงครบสิบแปดใบ',async p=>{await nonstop(p);await count(p,18);if(await button(p,/^ดูเที่ยวบินเพิ่มเติม/).isVisible())await more(p);assert.equal(await rows(p).count(),18);});
test('F05','การกระจายจุดแวะครบ 300 ใบ',async p=>{await more(p);const all=await rows(p).allTextContents();assert.equal(all.length,300);const groups=[0,0,0,0,0];for(const s of all){const n=s.includes('บินตรง')?0:Number(s.match(/แวะพัก (\d) ครั้ง/)?.[1]);assert(Number.isInteger(n)&&n<=4);groups[n]++;}assert.deepEqual(groups,[18,201,32,47,1]);});
test('F06','ช่วงราคาข้อมูลทั้งชุด',async p=>{await more(p);const a=await prices(p);assert.equal(Math.min(...a),7635);assert.equal(Math.max(...a),91085);});
test('F07','ช่วงราคาปกติเปลี่ยนตามคำค้น',async p=>{await sort(p,'เที่ยวบินยอดนิยม');await click(p,'ดูประวัติราคา');await has(p,/4,950/);await has(p,/7,200/);await p.keyboard.press('Escape');await nonstop(p);if(await button(p,'ดูประวัติราคา').isVisible())await click(p,'ดูประวัติราคา');await has(p,/6,400/);await has(p,/8,900/);});
test('F08','สูตรราคาอ้างอิงภายใน',async()=>{throw new Error('ยืนยันไม่ได้ผ่าน UI: ดัชนี [1]/[2]/[3] และสูตรเป็นข้อมูลภายใน ไม่อนุมานว่าผ่าน');});
test('F09','ผู้ขายสายการบินและ Gotogate',async p=>{await book(p);await has(p,/ไทยเวียดเจ๊ทแอร์/);await has(p,/สายการบิน/);await has(p,/Gotogate/);await has(p,/81/);assert.equal(await button(p,/ดำเนินการต่อ/).count(),2);});
test('F10','แสดงการเปลี่ยนสนามบินต่อเครื่อง',async p=>{await more(p);const r=rows(p).filter({hasText:/KIX.*ITM|TPE.*TSA|ICN.*GMP|เปลี่ยนสนามบิน/});assert.equal(await r.count(),23,'ต้องเห็นคำเตือนหรือรหัสสนามบินที่เปลี่ยน 23 ใบ');});
test('F11','สายการบินผู้ทำการบินจริง',async p=>{await more(p);const buttons=p.getByRole('button',{name:/^รายละเอียดเที่ยวบิน/});for(let i=0;i<await buttons.count();i++){await buttons.nth(i).click();if(/Air Japan|ANA Wings/.test(await text(p)))return;}assert.fail('ไม่พบผู้ทำการบินจริง Air Japan หรือ ANA Wings แม้ขยายทุกรายการ');});
test('F12','รายละเอียด VZ832 เครื่องบิน ที่วางขา CO2',async p=>{await rows(p).filter({hasText:'09:35'}).getByRole('button',{name:/รายละเอียด/}).click();await has(p,/737/);await has(p,/74\s*ซม/);await has(p,/396/);await has(p,/832/);});
test('F13','ตารางบินซ้ำราคาแตกต่าง',async p=>{await more(p);const a=await rows(p).allTextContents();assert(a.some(s=>s.includes('32,050')&&s.includes('14:15')));assert(a.some(s=>s.includes('32,132')&&s.includes('14:15')));});
test('F14','ราคาเปลี่ยนได้ตามเวลา',async()=>{throw new Error('ยืนยันไม่ได้ด้วยการรัน UI รอบเดียว: ต้องมี snapshot สองเวลาห่างกันราว 40 นาที ไม่บังคับราคาสดให้ตรงอดีต');});
test('F15','รายการตัวกรองจากชุดเต็ม',async p=>{await more(p);await filter(p,'สายการบิน');assert.equal(await p.getByRole('checkbox').count(),67,'64 สายการบิน + 3 พันธมิตร');await close(p);await filter(p,'สนามบินสำหรับต่อเครื่อง');assert.equal(await p.getByRole('checkbox').count(),33);});
test('F16','telemetry ที่ผู้ใช้ไม่เห็น',async()=>{throw new Error('ยืนยันไม่ได้ผ่าน UI: /log และ browserinfo เป็นคำขอเบื้องหลัง อยู่นอกข้อกำหนดตรวจจากสิ่งที่ผู้ใช้เห็น');});
